BEGIN;
SELECT COUNT(*) FROM tickets WHERE status = 'pending';
-- sees 3

                                                    INSERT INTO tickets (status)
                                                      VALUES ('pending');
                                                    COMMIT;

SELECT COUNT(*) FROM tickets WHERE status = 'pending';
-- sees 4 -- a new row "phantom-appeared" between
-- two runs of the identical query, in the same transaction
COMMIT;

-- Under REPEATABLE READ, T1's single transaction-wide snapshot
-- was taken before T2's INSERT committed, so T2's new row is
-- invisible to BOTH of T1's counts -- both would report 3.

-- T1                                    -- T2
BEGIN; -- (isolation level as specified)
SELECT COUNT(*) FROM tickets
  WHERE status = 'pending';  -- 5

                                          INSERT INTO tickets (status)
                                            VALUES ('pending');
                                          COMMIT;

SELECT COUNT(*) FROM tickets
  WHERE status = 'pending';  -- ?
COMMIT;

-- Both T1 and T2 run this concurrently, at REPEATABLE READ,
-- against a flight with exactly 1 seat remaining:

BEGIN;
SELECT seats_remaining FROM flights WHERE id = 1;
-- both T1 and T2 see 1

-- (application logic, in both sessions, sees 1 > 0 and decides to book)

UPDATE flights SET seats_remaining = seats_remaining - 1 WHERE id = 1;
INSERT INTO bookings (flight_id, customer_id) VALUES (1, /* T1's or T2's customer */);
COMMIT;

-- Fix 1: SERIALIZABLE, with a retry loop in the application
BEGIN ISOLATION LEVEL SERIALIZABLE;
SELECT seats_remaining FROM flights WHERE id = 1;
UPDATE flights SET seats_remaining = seats_remaining - 1 WHERE id = 1;
INSERT INTO bookings (flight_id, customer_id) VALUES (1, /* customer */);
COMMIT;
-- if this raises a serialization_failure error, the application must
-- catch it and retry the entire transaction from BEGIN

-- Fix 2: explicit row locking with SELECT ... FOR UPDATE
BEGIN;
SELECT seats_remaining FROM flights WHERE id = 1 FOR UPDATE;
-- this blocks a concurrent second transaction's FOR UPDATE on the same
-- row until the first one commits or rolls back, so the second
-- transaction re-reads the ALREADY-UPDATED value once it proceeds
UPDATE flights SET seats_remaining = seats_remaining - 1 WHERE id = 1;
INSERT INTO bookings (flight_id, customer_id) VALUES (1, /* customer */);
COMMIT;

