-- Client A's transaction, borrowing physical connection #7 from the pool:
BEGIN;
SET search_path = tenant_a;
SELECT * FROM orders LIMIT 1;
COMMIT;
-- Transaction-mode pooling returns connection #7 to the pool here.
-- search_path is STILL set to tenant_a on this physical connection --
-- nothing reset it.

-- Client B's transaction, unluckily borrowing the SAME physical
-- connection #7 next:
BEGIN;
SELECT * FROM orders LIMIT 1;   -- unexpectedly queries tenant_a's schema!
COMMIT;

-- Fix: scope the setting to the transaction instead of the session.
BEGIN;
SET LOCAL search_path = tenant_a;   -- automatically undone at COMMIT/ROLLBACK
SELECT * FROM orders LIMIT 1;
COMMIT;
-- Connection #7 returns to the pool with search_path back to its default.

-- Inside a request for tenant_x:
BEGIN;
SET search_path = tenant_x;
SELECT * FROM orders LIMIT 5;
COMMIT;
-- connection returned to the pool -- search_path is still tenant_x on it

-- Fix: use SET LOCAL instead of SET, so the setting is automatically
-- scoped to just this transaction and reverted at COMMIT/ROLLBACK.
BEGIN;
SET LOCAL search_path = tenant_x;
SELECT * FROM orders LIMIT 5;
COMMIT;
-- connection returned to the pool with search_path back to its default --
-- no tenant-specific state survives past this transaction.

-- Defense in depth: configure PgBouncer's server_reset_query
-- (e.g. DISCARD ALL) so any OTHER session state is also scrubbed
-- before a connection is handed to the next client, regardless of
-- whether every code path remembered to use SET LOCAL correctly.

